WITH latest_match AS (SELECT s.id, s.customer_id, s.balance, s.opened_date, latest.transaction_txn_type FROM accounts s JOIN LATERAL (SELECT c.txn_type AS transaction_txn_type FROM transactions c WHERE c.account_id = s.id AND c.txn_time <= s.opened_date ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT s.id, s.customer_id, s.balance, s.opened_date, (SELECT SUM(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS sum_account_balance FROM latest_match s ORDER BY sum_account_balance, balance DESC;
